import re as _re
_MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december']

# Musicals with posters, shown along the top of the Past musicals box (file stem in img/posters, title)
MUSICAL_POSTERS = [
    ('jesus-christ-superstar', 'Jesus Christ Superstar', '2008'), ('the-rocky-horror-show', 'The Rocky Horror Show', '2009'),
    ('suds', 'Suds', '2012'), ('reefer-madness', 'Reefer Madness', '2013'), ('the-wizard-of-oz', 'The Wizard of Oz', '2014'),
    ('seussical-the-musical', 'Seussical the Musical', '2015'), ('a-closer-walk-with-patsy-cline', 'A Closer Walk with Patsy Cline', '2015'),
    ('musical-memories', 'Musical Memories', '2016'), ('nunsensations', 'Nunsensations', '2018'),
    ('little-shop-of-horrors', 'Little Shop of Horrors', '2018'), ('mamma-mia', 'Mamma Mia!', '2019'),
]

# Festivals Portal Players hosted, shown as a highlighted line under the season heading
HOSTED = {
    '1993': 'Hosted the Theatre BC North Island Zone Drama Festival at The Capitol Theatre, April 25 to May 1, 1993',
    '2005–06': 'Hosted the 2006 Theatre BC North Island Zone Drama Festival at The Capitol Theatre, May 20–27, 2006: eight plays in eight nights, adjudicated by Ian Fenwick',
    '2008–09': 'Hosted the 2009 Theatre BC North Island Zone Drama Festival at The Capitol Theatre',
    '2010–11': 'Hosted the 2011 Theatre BC North Island Zone Drama Festival at The Capitol Theatre',
    '2014–15': 'Hosted the 2015 Theatre BC North Island Zone Drama Festival at The Capitol Theatre, May 16–22, 2015: seven plays in seven nights',
    '2018–19': 'With support from other North Island Zone clubs, Portal Players hosted Theatre BC’s Mainstage festival in Port Alberni, July 2019',
    '2023–24': 'Hosted the 2024 Theatre BC North Island Zone Drama Festival at The Capitol Theatre, May 2024',
}
MAINSTAGE = '2018–19'
# Festival note goes before this entry (overrides the May rule)
HOST_BEFORE = {'2010–11': 'GLEE year-end'}

def with_year(when, head):
    """Add the year to a month-only date, e.g. 'April' in 2017–18 -> 'April 2018'."""
    if not when or _re.search(r'\b(19|20)\d\d\b', when):
        return when
    m = _re.match(r'\s*([A-Za-z]+)', when)
    if not m:
        return when
    word = m.group(1).lower()
    hm = _re.match(r'(\d{4})(?:–(\d{2}))?$', head)
    if not hm:
        return when
    y1 = int(hm.group(1)); y2 = y1 + 1 if hm.group(2) else y1
    if word in _MONTHS:
        y = y1 if _MONTHS.index(word) >= 8 else y2   # seasons run September to August
    elif word == 'summer':
        y = y2
    else:
        return when
    sep = ', ' if _re.search(r'\d$', when) else ' '
    return f'{when}{sep}{y}'

def _season_pos(when, head):
    """Position of an entry within its season, by its first month (September first for split seasons)."""
    m=_re.search(r'(January|February|March|April|May|June|July|August|September|October|November|December|Summer)', when or '', _re.I)
    if not m: return None
    word=m.group(1).lower(); mo=7 if word=='summer' else _MONTHS.index(word)+1
    split='–' in head
    return (mo-9)%12 if split else mo   # split seasons: Sep=0 ... Aug=11

def _pnorm(x):
    x=_re.sub('<[^>]+>','',x).lower().replace('&amp;','and').replace('&','and').replace('’',"'")
    x=_re.sub(r'\(.*?\)','',x).strip(); x=_re.sub(r'^(stages|stages year-end show)\s*:\s*','',x)
    x=_re.sub(r'^(the|a|an)\s+','',x.strip())
    return _re.sub(r'[^a-z0-9 ]','',x).strip()

def poster_slots(head, entries):
    """Which entry each of a season's posters belongs beside: {stem: index}, or 'host' for a festival poster."""
    out={}
    for f,t in POSTERS.get(head,[]):
        if 'drama-festival' in f and head in HOSTED: out[f]='host'; continue
        pt=_pnorm(t) if t.startswith('An Evening') else _pnorm(t.split(':')[0])
        hits=[i for i,(w,ti,d) in enumerate(entries) if pt and (_pnorm(ti).startswith(pt[:14]) or pt.startswith(_pnorm(ti)[:14]))]
        if len(hits)!=1: hits=[i for i,(w,ti,d) in enumerate(entries) if pt[:14] in _pnorm(ti+' '+d)]
        if hits: out[f]=hits[0]
    return out

def _thumb_size(f):
    """Pixel size of a thumbnail, so the page can reserve its space before it loads (no jumping while scrolling)."""
    try:
        from PIL import Image
        import os
        here=os.path.dirname(os.path.abspath(__file__))
        with Image.open(os.path.join(here,'..','img','posters',f+'-thumb.jpg')) as im: return im.size
    except Exception:
        return (173,260)

# Photos shown small only: no link and no full-size file on the site
NOLINK = {'ballerinas-male-version'}
# Photos shown at full column width above their show (also not clickable)
BANNER = {'ballerinas-male-version'}

def _pics(items):
    out=''
    for f,t in items:
        w,h=_thumb_size(f)
        if f in NOLINK:
            out+=f'<span class="ps-nolink"><img src="img/posters/{f}-thumb.jpg" alt="{t}" width="{w}" height="{h}" loading="lazy"></span>'; continue
        out+=f'<a href="img/posters/{f}.jpg" target="_blank" title="{t} poster (opens full size)"><img src="img/posters/{f}-thumb.jpg" alt="{t} poster" width="{w}" height="{h}" loading="lazy"></a>'
    return out

def render():
    blocks=[]
    for head, note, entries in SEASONS:
        inline=poster_slots(head, entries)
        hl=''
        if head in HOSTED:
            logo='<img class="ps-tbc" src="img/theatre-bc.png" alt="Theatre BC" width="34" height="34">' if head==MAINSTAGE else ''
            hp=f'<p class="ps-host{" ps-mainstage" if head==MAINSTAGE else ""}">{logo}<span>{HOSTED[head]}</span></p>'
            hpics=[(f,t) for f,t in POSTERS.get(head,[]) if inline.get(f)=='host']
            hl=(f'<li class="ps-host-li ps-withposter"><div class="ps-side">{_pics(hpics)}</div><div class="ps-text">{hp}</div></li>' if hpics
                else f'<li class="ps-host-li">{hp}</li>')
            # Zone festivals are held in May; Mainstage 2019 was in July. Place the note where it falls in the season.
            host_pos=_season_pos('July' if head==MAINSTAGE else 'May', head)
        lis=''; placed=not hl
        for idx,(when, title, detail) in enumerate(entries):
            pos=_season_pos(when, head)
            if not placed and (HOST_BEFORE[head] in title if head in HOST_BEFORE else (pos is not None and pos>host_pos)):
                lis+=hl; placed=True
            when=with_year(when, head)
            w=f'<span class="ps-when">{when}</span>' if when else ''
            d=f'<span class="ps-detail">{detail}</span>' if detail else ''
            t2=title if '<em>' in title else f'<b>{title}</b>'
            t2=_re.sub(r'(</em>|</b>)?\s*\(([^()]*)\)(</b>)?\s*$', lambda m:(m.group(1) or '')+(m.group(3) or '')+f' <span class="ps-paren">({m.group(2)})</span>', t2)
            allp=[(f,t) for f,t in POSTERS.get(head,[]) if inline.get(f)==idx]
            wide=''.join(f'<div class="ps-banner"><img src="img/posters/{f}-thumb.jpg" alt="{t}" width="{_thumb_size(f)[0]}" height="{_thumb_size(f)[1]}" loading="lazy"></div>' for f,t in allp if f in BANNER)
            mine=[(f,t) for f,t in allp if f not in BANNER]
            if mine:
                pics=_pics(mine)
                lis+=f'<li class="ps-withposter">{wide and ""}<div class="ps-side">{pics}</div><div class="ps-text">{w}<span class="ps-title">{t2}</span>{d}</div></li>'
                if wide: lis=lis[:lis.rfind('<li class="ps-withposter">')]+f'<li class="ps-bannerli">{wide}</li>'+lis[lis.rfind('<li class="ps-withposter">'):]
            else:
                lis+=f'<li>{wide}{w}<span class="ps-title">{t2}</span>{d}</li>'
        if not placed: lis+=hl
        n=f'<p class="ps-note">{note}</p>' if note else ''
        after=''
        ps=''.join(f'<a href="img/posters/{f}.jpg" target="_blank" title="{t} poster (opens full size)"><img src="img/posters/{f}-thumb.jpg" alt="{t} poster" height="130" loading="lazy"></a>' for f,t in POSTERS.get(head,[]) if f not in inline)
        ps=f'<div class="ps-posters">{ps}</div>' if ps else ''
        blocks.append(f'<div class="ps-season">{ps}<h3>{head}</h3>{n}<ul>{lis}</ul>{after}</div>')
    # STAGES callout, gathered from the season lists
    st_items=[]; st_pics=[]
    for head,note,entries in SEASONS:
        slots=poster_slots(head, entries)
        for idx,(when,title,detail) in enumerate(entries):
            if 'STAGES' not in title: continue
            wy=with_year(when, head); m=_re.search(r'(19|20)\d\d',wy); y=m.group(0) if m else head[:4]
            mon=_re.sub(r',?\s*(19|20)\d\d','',wy).strip()
            t=_re.sub(r'^STAGES( year-end show)?:\s*','',title)
            st_items.append(f'<li><span class="ps-when">{y}{" · "+mon if mon else ""}</span><span class="ps-title">{t}</span></li>')
            for f,pt in POSTERS.get(head,[]):
                if slots.get(f)==idx and f not in NOLINK and 'alternate' not in f:
                    w,h=_thumb_size(f)
                    st_pics.append(f'<div class="ps-pfig"><span class="ps-when ps-pyear">{y}</span><a href="img/posters/{f}.jpg" target="_blank" title="{pt} poster (opens full size)"><img src="img/posters/{f}-thumb.jpg" alt="{pt} poster" width="{round(w*130/h)}" height="130" loading="lazy"></a></div>')
    stl=''.join(st_items); sps=''.join(st_pics)
    mus=''.join(f'<li><span class="ps-when">{y} · {m}</span><span class="ps-title"><em>{t.replace(" (panto)","")}</em>{" <span class=ps-paren>(panto)</span>" if "(panto)" in t else ""}</span></li>' for y,m,t in MUSICALS)
    mps=''.join(f'<div class="ps-pfig"><span class="ps-when ps-pyear">{y}</span><a href="img/posters/{f}.jpg" target="_blank" title="{t} poster (opens full size)"><img src="img/posters/{f}-thumb.jpg" alt="{t} poster" width="{round(_thumb_size(f)[0]*130/_thumb_size(f)[1])}" height="130"></a></div>' for f,t,y in MUSICAL_POSTERS)
    return f'''
<section class="block past-seasons" id="past-seasons">
  <div class="wrap">
    <div class="head"><div><div class="eyebrow">Since 1988</div><h2>Past seasons</h2></div></div>
    <p class="ps-intro">Plays, musicals, pantos, one-acts, readings and festival entries staged by Portal Players over the decades. Click on the poster thumbnails to see a larger version.</p>
    <div class="note" style="max-width:760px">This list is extensive, but it may not be complete. Know of a production we’ve missed, or spot a name or date to correct? Please email <a href="mailto:capitoltheatre@shaw.ca?subject=Past%20seasons">capitoltheatre@shaw.ca</a> so we can add it.</div>
    <div class="ps-grid">{''.join(blocks)}</div>
    <div class="ps-musicals">
      <h3>Past Musicals</h3>
      <div class="ps-posters">{mps}</div>
      <ul>{mus}</ul>
    </div>
    <div class="ps-musicals ps-stages">
      <h3>Past STAGES Productions</h3>
      <p class="ps-note">Our STAGES Youth Theatre program.</p>
      <div class="ps-posters">{sps}</div>
      <ul>{stl}</ul>
    </div>
  </div>
</section>'''

